"""Encrypted file storage on local disk (a bind mount in production)."""

import os
import uuid
from pathlib import Path

from app.core.config import get_settings
from app.core.crypto import decrypt_bytes, encrypt_bytes


def _root() -> Path:
    root = Path(get_settings().documents_dir)
    root.mkdir(parents=True, exist_ok=True, mode=0o700)
    return root


def _path(storage_key: str) -> Path:
    # storage keys are generated by us ("<org uuid>/<doc uuid>.bin"); refuse anything else
    org, _, name = storage_key.partition("/")
    uuid.UUID(org)
    uuid.UUID(name.removesuffix(".bin"))
    return _root() / org / name


def save(org_id: uuid.UUID, doc_id: uuid.UUID, data: bytes) -> str:
    key = f"{org_id}/{doc_id}.bin"
    path = _path(key)
    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    tmp = path.with_suffix(".tmp")
    tmp.write_bytes(encrypt_bytes(data, str(doc_id).encode()))
    os.replace(tmp, path)  # atomic: never a half-written file
    return key


def load(storage_key: str, doc_id: uuid.UUID) -> bytes:
    return decrypt_bytes(_path(storage_key).read_bytes(), str(doc_id).encode())


def delete(storage_key: str) -> None:
    _path(storage_key).unlink(missing_ok=True)
